CREATE COLUMN TABLE "TEST_AP"."BSJ1" ("ID" INTEGER CS_INT NOT NULL , "TaskID" INTEGER CS_INT NOT NULL , "Type" NVARCHAR(50), "Params" NCLOB MEMORY THRESHOLD 1000, "RunAs" SMALLINT CS_INT, "Status" NVARCHAR(1) DEFAULT 'S', "PostTask" INTEGER CS_INT, "PreTask" INTEGER CS_INT, "LastDate" LONGDATE CS_LONGDATE, "LastTime" SMALLINT CS_INT, "Retry" INTEGER CS_INT DEFAULT 0, "TimeOut" INTEGER CS_INT DEFAULT 20, "Message" NVARCHAR(200), PRIMARY KEY ("ID", "TaskID")) UNLOAD PRIORITY 5  AUTO MERGE 